"""Parser for the minisql SELECT dialect."""

from dataclasses import dataclass, field
from typing import List, Optional, Tuple

from .errors import QueryError
from .lexer import Token, tokenize


KEYWORDS = {
    "SELECT",
    "DISTINCT",
    "FROM",
    "WHERE",
    "GROUP",
    "BY",
    "HAVING",
    "ORDER",
    "LIMIT",
    "OFFSET",
    "ASC",
    "DESC",
    "AS",
    "OR",
    "AND",
    "NOT",
    "IS",
    "NULL",
    "IN",
    "BETWEEN",
    "LIKE",
    "TRUE",
    "FALSE",
}


class Expr:
    """Base class for expression nodes."""

    span: Optional[Tuple[int, int]] = None


@dataclass
class Literal(Expr):
    value: object
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class Column(Expr):
    name: str
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class Unary(Expr):
    op: str
    operand: Expr
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class Binary(Expr):
    op: str
    left: Expr
    right: Expr
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class InList(Expr):
    operand: Expr
    items: List[Expr]
    negated: bool
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class Like(Expr):
    operand: Expr
    pattern: Expr
    negated: bool
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class FuncCall(Expr):
    name: str
    args: List[Expr]
    star: bool = False
    span: Optional[Tuple[int, int]] = field(default=None, compare=False, repr=False)


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    desc: bool = False


@dataclass
class Query:
    distinct: bool
    select_star: bool
    select: List[SelectItem]
    table: str
    where: Optional[Expr]
    group_by: List[Expr]
    having: Optional[Expr]
    order_by: List[OrderItem]
    limit: Optional[int]
    offset: Optional[int]


COMPARISONS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    def parse(self) -> Query:
        self._expect_keyword("SELECT")
        distinct = self._accept_keyword("DISTINCT")

        select_star = False
        select: List[SelectItem] = []
        if self._accept_symbol("*"):
            select_star = True
        else:
            select.append(self._parse_select_item())
            while self._accept_symbol(","):
                select.append(self._parse_select_item())

        self._expect_keyword("FROM")
        table = self._parse_name("table name")

        where = None
        group_by: List[Expr] = []
        having = None
        order_by: List[OrderItem] = []
        limit = None
        offset = None

        if self._accept_keyword("WHERE"):
            where = self._parse_expr()

        if self._accept_keyword("GROUP"):
            self._expect_keyword("BY")
            group_by.append(self._parse_expr())
            while self._accept_symbol(","):
                group_by.append(self._parse_expr())

        if self._accept_keyword("HAVING"):
            having = self._parse_expr()

        if self._accept_keyword("ORDER"):
            self._expect_keyword("BY")
            order_by.append(self._parse_order_item())
            while self._accept_symbol(","):
                order_by.append(self._parse_order_item())

        if self._accept_keyword("LIMIT"):
            limit = self._parse_limit_value("LIMIT")
            if self._accept_keyword("OFFSET"):
                offset = self._parse_limit_value("OFFSET")

        self._accept_symbol(";")
        if self._peek().kind != "EOF":
            self._error("unexpected token %r" % (self._peek().value,))

        return Query(
            distinct=distinct,
            select_star=select_star,
            select=select,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    # ------------------------------------------------------------------
    # Clauses

    def _parse_select_item(self) -> SelectItem:
        expr = self._parse_expr()
        alias = None
        if self._accept_keyword("AS"):
            alias = self._parse_name("alias")
        elif self._is_alias():
            alias = self._consume().value  # type: ignore[assignment]
        return SelectItem(expr, alias)

    def _parse_order_item(self) -> OrderItem:
        expr = self._parse_expr()
        desc = False
        if self._accept_keyword("ASC"):
            desc = False
        elif self._accept_keyword("DESC"):
            desc = True
        return OrderItem(expr, desc)

    def _parse_limit_value(self, clause: str) -> int:
        token = self._peek()
        if token.kind != "NUMBER" or not isinstance(token.value, int):
            self._error("%s requires a non-negative integer" % clause)
        assert isinstance(token.value, int)
        if token.value < 0:
            self._error("%s requires a non-negative integer" % clause)
        self.pos += 1
        return token.value

    # ------------------------------------------------------------------
    # Expressions

    def _parse_expr(self) -> Expr:
        return self._parse_or()

    def _parse_or(self) -> Expr:
        left = self._parse_and()
        while self._accept_keyword("OR"):
            right = self._parse_and()
            left = Binary("OR", left, right, span=(left.span[0], right.span[1]))
        return left

    def _parse_and(self) -> Expr:
        left = self._parse_not()
        while self._accept_keyword("AND"):
            right = self._parse_not()
            left = Binary("AND", left, right, span=(left.span[0], right.span[1]))
        return left

    def _parse_not(self) -> Expr:
        if self._at_keyword("NOT"):
            token = self._consume()
            operand = self._parse_not()
            return Unary("NOT", operand, span=(token.start, operand.span[1]))
        return self._parse_comparison()

    def _parse_comparison(self) -> Expr:
        left = self._parse_additive()

        if self._accept_keyword("IS"):
            negated = self._accept_keyword("NOT")
            null_token = self._expect_keyword("NULL")
            return IsNull(left, negated, span=(left.span[0], null_token.end))

        negated = False
        if self._at_keyword("NOT") and self._peek_keyword(1) in ("IN", "BETWEEN", "LIKE"):
            self._consume()
            negated = True

        if self._accept_keyword("IN"):
            self._expect_symbol("(")
            items = [self._parse_expr()]
            while self._accept_symbol(","):
                items.append(self._parse_expr())
            close = self._expect_symbol(")")
            return InList(left, items, negated, span=(left.span[0], close.end))

        if self._accept_keyword("BETWEEN"):
            low = self._parse_additive()
            self._expect_keyword("AND")
            high = self._parse_additive()
            return Between(
                left, low, high, negated, span=(left.span[0], high.span[1])
            )

        if self._accept_keyword("LIKE"):
            pattern = self._parse_additive()
            return Like(left, pattern, negated, span=(left.span[0], pattern.span[1]))

        token = self._peek()
        if token.kind == "SYMBOL" and token.value in COMPARISONS:
            self.pos += 1
            right = self._parse_additive()
            return Binary(
                token.value, left, right, span=(left.span[0], right.span[1])
            )

        return left

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == "SYMBOL" and token.value in ("+", "-", "||"):
                self.pos += 1
                right = self._parse_multiplicative()
                left = Binary(
                    token.value, left, right, span=(left.span[0], right.span[1])
                )
            else:
                break
        return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == "SYMBOL" and token.value in ("*", "/"):
                self.pos += 1
                right = self._parse_unary()
                left = Binary(
                    token.value, left, right, span=(left.span[0], right.span[1])
                )
            else:
                break
        return left

    def _parse_unary(self) -> Expr:
        if self._at_symbol("-"):
            token = self._consume()
            operand = self._parse_unary()
            return Unary("-", operand, span=(token.start, operand.span[1]))
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        token = self._peek()

        if token.kind == "NUMBER":
            self.pos += 1
            return Literal(token.value, span=(token.start, token.end))

        if token.kind == "STRING":
            self.pos += 1
            return Literal(token.value, span=(token.start, token.end))

        if token.kind == "QNAME":
            self.pos += 1
            return Column(token.value, span=(token.start, token.end))  # type: ignore[arg-type]

        if token.kind == "NAME":
            upper = str(token.value).upper()
            if upper == "NULL":
                self.pos += 1
                return Literal(None, span=(token.start, token.end))
            if upper == "TRUE":
                self.pos += 1
                return Literal(True, span=(token.start, token.end))
            if upper == "FALSE":
                self.pos += 1
                return Literal(False, span=(token.start, token.end))
            if upper in KEYWORDS:
                self._error("unexpected keyword %r" % (token.value,))
            if self._peek(1).kind == "SYMBOL" and self._peek(1).value == "(":
                return self._parse_function_call()
            self.pos += 1
            return Column(token.value, span=(token.start, token.end))  # type: ignore[arg-type]

        if token.kind == "SYMBOL" and token.value == "(":
            start = token.start
            self.pos += 1
            expr = self._parse_expr()
            close = self._expect_symbol(")")
            expr.span = (start, close.end)
            return expr

        self._error("expected an expression")

    def _parse_function_call(self) -> Expr:
        name_token = self._consume()
        self._expect_symbol("(")
        star = False
        args: List[Expr] = []
        if self._accept_symbol("*"):
            star = True
        elif not self._at_symbol(")"):
            args.append(self._parse_expr())
            while self._accept_symbol(","):
                args.append(self._parse_expr())
        close = self._expect_symbol(")")
        return FuncCall(
            str(name_token.value),
            args,
            star,
            span=(name_token.start, close.end),
        )

    # ------------------------------------------------------------------
    # Token helpers

    def _peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _peek_keyword(self, offset: int = 0) -> Optional[str]:
        token = self._peek(offset)
        if token.kind == "NAME":
            return str(token.value).upper()
        return None

    def _at_keyword(self, word: str) -> bool:
        return self._peek_keyword() == word

    def _accept_keyword(self, word: str) -> bool:
        if self._at_keyword(word):
            self.pos += 1
            return True
        return False

    def _expect_keyword(self, word: str) -> Token:
        if not self._at_keyword(word):
            self._error("expected %s" % word)
        return self._consume()

    def _at_symbol(self, symbol: str) -> bool:
        token = self._peek()
        return token.kind == "SYMBOL" and token.value == symbol

    def _accept_symbol(self, symbol: str) -> bool:
        if self._at_symbol(symbol):
            self.pos += 1
            return True
        return False

    def _expect_symbol(self, symbol: str) -> Token:
        if not self._at_symbol(symbol):
            self._error("expected %r" % symbol)
        return self._consume()

    def _is_alias(self) -> bool:
        token = self._peek()
        if token.kind == "QNAME":
            return True
        if token.kind == "NAME":
            return str(token.value).upper() not in KEYWORDS
        return False

    def _parse_name(self, what: str) -> str:
        token = self._peek()
        if token.kind == "QNAME":
            self.pos += 1
            return str(token.value)
        if token.kind == "NAME" and str(token.value).upper() not in KEYWORDS:
            self.pos += 1
            return str(token.value)
        self._error("expected %s" % what)

    def _consume(self) -> Token:
        token = self._peek()
        self.pos += 1
        return token

    def _error(self, message: str):
        token = self._peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        raise QueryError("%s at position %d" % (message, token.start))


def parse(sql: str) -> Query:
    """Parse a complete query string into a :class:`Query`."""
    return Parser(sql).parse()

