        args: List[Expr] = []
        if self._accept_symbol("*"):
            star = True
        elif not self._at_symbol(")"):
            args.append(self._parse_expr())
            while self._accept_symbol(","):
                args.append(self._parse_expr())
        close = self._expect_symbol(")")
        return FuncCall(
            str(name_token.value),
            args,
            star,
            span=(name_token.start, close.end),
        )

    # ------------------------------------------------------------------
    # Token helpers

    def _peek(self, offset: int = 0) -> Token:
        index = self.pos + offset
        if index >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[index]

    def _peek_keyword(self, offset: int = 0) -> Optional[str]:
        token = self._peek(offset)
        if token.kind == "NAME":
            return str(token.value).upper()
        return None

    def _at_keyword(self, word: str) -> bool:
        return self._peek_keyword() == word

    def _accept_keyword(self, word: str) -> bool:
        if self._at_keyword(word):
            self.pos += 1
            return True
        return False

    def _expect_keyword(self, word: str) -> Token:
        if not self._at_keyword(word):
            self._error("expected %s" % word)
        return self._consume()

    def _at_symbol(self, symbol: str) -> bool:
        token = self._peek()
        return token.kind == "SYMBOL" and token.value == symbol

    def _accept_symbol(self, symbol: str) -> bool:
        if self._at_symbol(symbol):
            self.pos += 1
            return True
        return False

    def _expect_symbol(self, symbol: str) -> Token:
        if not self._at_symbol(symbol):
            self._error("expected %r" % symbol)
        return self._consume()

    def _is_alias(self) -> bool:
        token = self._peek()
        if token.kind == "QNAME":
            return True
        if token.kind == "NAME":
            return str(token.value).upper() not in KEYWORDS
        return False

    def _parse_name(self, what: str) -> str:
        token = self._peek()
        if token.kind == "QNAME":
            self.pos += 1
            return str(token.value)
        if token.kind == "NAME" and str(token.value).upper() not in KEYWORDS:
            self.pos += 1
            return str(token.value)
        self._error("expected %s" % what)

    def _consume(self) -> Token:
        token = self._peek()
        self.pos += 1
        return token

    def _error(self, message: str):
        token = self._peek()
        if token.kind == "EOF":
            raise QueryError("%s at end of query" % message)
        raise QueryError("%s at position %d" % (message, token.start))


def parse(sql: str) -> Query:
    """Parse a complete query string into a :class:`Query`."""
    return Parser(sql).parse()
