"""Query execution for minisql."""

import csv
import os
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from functools import cmp_to_key
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

from .errors import QueryError
from .parser import (
    Between,
    Binary,
    Column,
    Expr,
    FuncCall,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    Unary,
)


AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
SCALAR_FUNCTIONS = {"LOWER", "UPPER", "LENGTH", "ABS", "ROUND", "COALESCE"}

_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


@dataclass
class Result:
    """The columns and rows produced by a query."""

    columns: List[str]
    rows: List[Tuple[object, ...]]


@dataclass
class Table:
    headers: List[str]
    rows: List[List[object]]
    columns: Dict[str, int]


@dataclass
class EvalContext:
    table: Table
    row: Optional[List[object]] = None
    group: Optional[List[List[object]]] = None
    group_values: Optional[Dict[tuple, object]] = None


# ----------------------------------------------------------------------
# Public entry point


def run(sql: str, directory: str = ".") -> Result:
    """Run ``sql`` against the CSV files in ``directory``."""
    query = _parse(sql)
    table = load_table(directory, query.table)
    columns, rows = execute(query, table, sql)
    return Result(columns, rows)


def _parse(sql: str) -> Query:
    from .parser import parse

    return parse(sql)


# ----------------------------------------------------------------------
# Reading tables


def load_table(directory: str, name: str) -> Table:
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", newline="", encoding="utf-8-sig") as handle:
            reader = csv.reader(handle)
            try:
                headers = next(reader)
            except StopIteration:
                raise QueryError("table %r has no header" % name)
            rows: List[List[object]] = []
            for raw_row in reader:
                if not raw_row:
                    continue
                row = []
                for index in range(len(headers)):
                    raw = raw_row[index] if index < len(raw_row) else ""
                    row.append(_convert_field(raw))
                rows.append(row)
    except FileNotFoundError:
        raise QueryError("unknown table: %s" % name) from None
    except OSError as exc:
        raise QueryError(str(exc)) from None
    except csv.Error as exc:
        raise QueryError(str(exc)) from None

    column_map: Dict[str, int] = {}
    for index, header in enumerate(headers):
        column_map.setdefault(header.casefold(), index)
    return Table(headers, rows, column_map)


def _convert_field(text: str):
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        return int(text)
    if _DECIMAL_RE.fullmatch(text):
        return float(text)
    return text


def _resolve_column(table: Table, name: str) -> int:
    try:
        return table.columns[name.casefold()]
    except KeyError:
        raise QueryError("unknown column: %s" % name) from None


# ----------------------------------------------------------------------
# Expression helpers


def _is_number(value) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _type_name(value) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if _is_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _group_key(value):
    """A hashable key making SQL-ish equality explicit for grouping/distinct."""
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("boolean", value)
    if _is_number(value):
        return ("number", value)
    return ("string", value)


def _expr_signature(expr: Expr):
    """Canonical form used to compare expressions structurally."""
    if isinstance(expr, Literal):
        value = expr.value
        if value is None:
            return ("literal", "null")
        if isinstance(value, bool):
            return ("literal", "boolean", value)
        if _is_number(value):
            return ("literal", "number", value)
        return ("literal", "string", value)
    if isinstance(expr, Column):
        return ("column", expr.name.casefold())
    if isinstance(expr, Unary):
        return ("unary", expr.op, _expr_signature(expr.operand))
    if isinstance(expr, Binary):
        return (
            "binary",
            expr.op,
            _expr_signature(expr.left),
            _expr_signature(expr.right),
        )
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, _expr_signature(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            expr.negated,
            _expr_signature(expr.operand),
            tuple(_expr_signature(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            _expr_signature(expr.operand),
            _expr_signature(expr.low),
            _expr_signature(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            expr.negated,
            _expr_signature(expr.operand),
            _expr_signature(expr.pattern),
        )
    if isinstance(expr, FuncCall):
        return (
            "call",
            expr.name.upper(),
            expr.star,
            tuple(_expr_signature(arg) for arg in expr.args),
        )
    raise QueryError("invalid expression")


def _children(expr: Expr) -> Iterable[Expr]:
    if isinstance(expr, Unary):
        return (expr.operand,)
    if isinstance(expr, Binary):
        return (expr.left, expr.right)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, InList):
        return [expr.operand] + list(expr.items)
    if isinstance(expr, Between):
        return (expr.operand, expr.low, expr.high)
    if isinstance(expr, Like):
        return (expr.operand, expr.pattern)
    return ()


def _contains_aggregate(expr: Expr) -> bool:
    if isinstance(expr, FuncCall) and expr.name.upper() in AGGREGATES:
        return True
    return any(_contains_aggregate(child) for child in _children(expr))


def _check_function(expr: FuncCall) -> None:
    name = expr.name.upper()
    if name in AGGREGATES:
        if name == "COUNT":
            if expr.star:
                if expr.args:
                    raise QueryError("COUNT(*) takes no arguments")
            elif len(expr.args) != 1:
                raise QueryError("COUNT takes exactly one argument")
        else:
            if expr.star or len(expr.args) != 1:
                raise QueryError("%s takes exactly one argument" % name)
        return

    if name not in SCALAR_FUNCTIONS:
        raise QueryError("unknown function: %s" % expr.name)
    if expr.star:
        raise QueryError("%s does not accept '*'" % expr.name)
    count = len(expr.args)
    if name == "ROUND":
        if count not in (1, 2):
            raise QueryError("ROUND takes one or two arguments")
    elif name == "COALESCE":
        if count < 1:
            raise QueryError("COALESCE takes at least one argument")
    else:
        if count != 1:
            raise QueryError("%s takes exactly one argument" % name)


def _validate_expr(
    expr: Expr,
    table: Table,
    group_signatures: Optional[set] = None,
    inside_aggregate: bool = False,
    in_where: bool = False,
    in_group_by: bool = False,
) -> None:
    if (
        group_signatures is not None
        and not inside_aggregate
        and _expr_signature(expr) in group_signatures
    ):
        return

    if isinstance(expr, Column):
        _resolve_column(table, expr.name)
        if group_signatures is not None and not inside_aggregate:
            raise QueryError(
                "column %s must appear in GROUP BY" % expr.name
            )
        return

    if isinstance(expr, FuncCall):
        _check_function(expr)
        name = expr.name.upper()
        if name in AGGREGATES:
            if in_where:
                raise QueryError("aggregate functions are not allowed in WHERE")
            if in_group_by:
                raise QueryError("aggregate functions are not allowed in GROUP BY")
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            for arg in expr.args:
                _validate_expr(
                    arg,
                    table,
                    group_signatures=None,
                    inside_aggregate=True,
                    in_where=in_where,
                    in_group_by=in_group_by,
                )
            return
        for arg in expr.args:
            _validate_expr(
                arg,
                table,
                group_signatures=group_signatures,
                inside_aggregate=inside_aggregate,
                in_where=in_where,
                in_group_by=in_group_by,
            )
        return

    for child in _children(expr):
        _validate_expr(
            child,
            table,
            group_signatures=group_signatures,
            inside_aggregate=inside_aggregate,
            in_where=in_where,
            in_group_by=in_group_by,
        )


# ----------------------------------------------------------------------
# Value operations


def _compare_order(left, right) -> int:
    if _is_number(left) and _is_number(right):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, str) and isinstance(right, str):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    if isinstance(left, bool) and isinstance(right, bool):
        if left < right:
            return -1
        if left > right:
            return 1
        return 0
    raise QueryError(
        "cannot compare %s with %s" % (_type_name(left), _type_name(right))
    )


def _compare_values(op: str, left, right):
    if left is None or right is None:
        return None
    order = _compare_order(left, right)
    if op == "=":
        return order == 0
    if op in ("!=", "<>"):
        return order != 0
    if op == "<":
        return order < 0
    if op == "<=":
        return order <= 0
    if op == ">":
        return order > 0
    if op == ">=":
        return order >= 0
    raise QueryError("unknown comparison operator: %s" % op)


def _arithmetic(op: str, left, right):
    if left is None or right is None:
        return None
    if not _is_number(left) or not _is_number(right):
        raise QueryError(
            "cannot apply %s to %s and %s"
            % (op, _type_name(left), _type_name(right))
        )
    try:
        if op == "/":
            if right == 0:
                return None
            return left / right
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        elif op == "*":
            result = left * right
        else:
            raise QueryError("unknown arithmetic operator: %s" % op)
    except OverflowError:
        raise QueryError("numeric overflow") from None

    if isinstance(left, int) and isinstance(right, int):
        return result
    return float(result)


def _concat(left, right):
    if left is None or right is None:
        return None
    return _text(left) + _text(right)


def _text(value) -> str:
    if isinstance(value, str):
        return value
    return str(value)


def _like_match(value: str, pattern: str) -> bool:
    pieces = []
    for char in pattern:
        if char == "%":
            pieces.append(".*")
        elif char == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(char))
    return re.fullmatch("".join(pieces), value, re.DOTALL) is not None


def _round_value(value, digits: Optional[int]):
    if not _is_number(value):
        raise QueryError("ROUND requires a number")
    if digits is not None and (isinstance(digits, bool) or not isinstance(digits, int)):
        raise QueryError("ROUND's second argument must be an integer")

    try:
        number = Decimal(str(value))
        extra = 0 if digits is None else abs(digits)
        with localcontext() as context:
            context.prec = max(28, len(number.as_tuple().digits) + extra + 10)
            if digits is None:
                rounded = number.quantize(Decimal(1), rounding=ROUND_HALF_UP)
                return int(rounded)
            quantum = Decimal(1).scaleb(-digits)
            rounded = number.quantize(quantum, rounding=ROUND_HALF_UP)
            return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("cannot round value") from None


def _and_values(left, right):
    if _is_boolean_or_null(left) and _is_boolean_or_null(right):
        if left is False or right is False:
            return False
        if left is None or right is None:
            return None
        return True
    raise QueryError("AND requires boolean operands")


def _or_values(left, right):
    if _is_boolean_or_null(left) and _is_boolean_or_null(right):
        if left is True or right is True:
            return True
        if left is None or right is None:
            return None
        return False
    raise QueryError("OR requires boolean operands")


def _is_boolean_or_null(value) -> bool:
    return value is None or isinstance(value, bool)


def _ensure_boolean_or_null(value) -> None:
    if not _is_boolean_or_null(value):
        raise QueryError("expected a boolean, got %s" % _type_name(value))


# ----------------------------------------------------------------------
# Expression evaluation


def _is_aggregate_call(expr: Expr) -> bool:
    return isinstance(expr, FuncCall) and expr.name.upper() in AGGREGATES


def _eval_expr(expr: Expr, context: EvalContext):
    if context.group_values is not None and not _is_aggregate_call(expr):
        signature = _expr_signature(expr)
        if signature in context.group_values:
            return context.group_values[signature]

    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, Column):
        index = _resolve_column(context.table, expr.name)
        if context.row is None:
            raise QueryError("column %s must appear in GROUP BY" % expr.name)
        return context.row[index]

    if isinstance(expr, Unary):
        value = _eval_expr(expr.operand, context)
        if expr.op == "NOT":
            if value is None:
                return None
            if not isinstance(value, bool):
                raise QueryError("NOT requires a boolean")
            return not value
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("unary - requires a number")
        return -value

    if isinstance(expr, Binary):
        if expr.op == "AND":
            left = _eval_expr(expr.left, context)
            _ensure_boolean_or_null(left)
            if left is False:
                return False
            right = _eval_expr(expr.right, context)
            _ensure_boolean_or_null(right)
            return _and_values(left, right)

        if expr.op == "OR":
            left = _eval_expr(expr.left, context)
            _ensure_boolean_or_null(left)
            if left is True:
                return True
            right = _eval_expr(expr.right, context)
            _ensure_boolean_or_null(right)
            return _or_values(left, right)

        left = _eval_expr(expr.left, context)
        right = _eval_expr(expr.right, context)
        if expr.op in ("+", "-", "*", "/"):
            return _arithmetic(expr.op, left, right)
        if expr.op == "||":
            return _concat(left, right)
        return _compare_values(expr.op, left, right)

    if isinstance(expr, IsNull):
        value = _eval_expr(expr.operand, context)
        result = value is None
        return not result if expr.negated else result

    if isinstance(expr, InList):
        return _eval_in(expr, context)

    if isinstance(expr, Between):
        value = _eval_expr(expr.operand, context)
        low = _eval_expr(expr.low, context)
        result = _compare_values("<=", low, value)
        if result is not False:
            high = _eval_expr(expr.high, context)
            result = _and_values(result, _compare_values("<=", value, high))
        if expr.negated and result is not None:
            result = not result
        return result

    if isinstance(expr, Like):
        value = _eval_expr(expr.operand, context)
        pattern = _eval_expr(expr.pattern, context)
        if value is None or pattern is None:
            return None
        if not isinstance(value, str) or not isinstance(pattern, str):
            raise QueryError("LIKE requires string operands")
        result = _like_match(value, pattern)
        return not result if expr.negated else result

    if isinstance(expr, FuncCall):
        if expr.name.upper() in AGGREGATES:
            return _eval_aggregate(expr, context)
        return _eval_scalar(expr, context)

    raise QueryError("invalid expression")


def _eval_in(expr: InList, context: EvalContext):
    value = _eval_expr(expr.operand, context)
    saw_null = value is None
    found = False
    for item_expr in expr.items:
        item = _eval_expr(item_expr, context)
        if item is None:
            saw_null = True
        elif value is not None and _compare_values("=", value, item) is True:
            found = True
            break

    if found:
        result = True
    elif saw_null:
        result = None
    else:
        result = False
    if expr.negated and result is not None:
        result = not result
    return result


def _eval_scalar(expr: FuncCall, context: EvalContext):
    name = expr.name.upper()

    if name == "COALESCE":
        for arg in expr.args:
            value = _eval_expr(arg, context)
            if value is not None:
                return value
        return None

    values = [_eval_expr(arg, context) for arg in expr.args]

    if name in ("LOWER", "UPPER", "LENGTH"):
        value = values[0]
        if value is None:
            return None
        if not isinstance(value, str):
            raise QueryError("%s requires a string" % name)
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        value = values[0]
        if value is None:
            return None
        if not _is_number(value):
            raise QueryError("ABS requires a number")
        return abs(value)

    if name == "ROUND":
        value = values[0]
        if len(values) == 1:
            if value is None:
                return None
            return _round_value(value, None)
        digits = values[1]
        if value is None or digits is None:
            return None
        return _round_value(value, digits)

    raise QueryError("unknown function: %s" % expr.name)


def _eval_aggregate(expr: FuncCall, context: EvalContext):
    if context.group is None:
        raise QueryError("aggregate function used outside a grouped query")

    name = expr.name.upper()

    if name == "COUNT":
        if expr.star:
            return len(context.group)
        count = 0
        for row in context.group:
            row_context = EvalContext(context.table, row=row)
            if _eval_expr(expr.args[0], row_context) is not None:
                count += 1
        return count

    argument = expr.args[0]
    values = []
    for row in context.group:
        row_context = EvalContext(context.table, row=row)
        value = _eval_expr(argument, row_context)
        if value is not None:
            values.append(value)

    if not values:
        return None

    if name == "SUM":
        total = 0
        has_float = False
        for value in values:
            if not _is_number(value):
                raise QueryError("SUM requires numbers")
            total += value
            if isinstance(value, float):
                has_float = True
        return float(total) if has_float else total

    if name == "AVG":
        total = 0
        for value in values:
            if not _is_number(value):
                raise QueryError("AVG requires numbers")
            total += value
        return total / len(values)

    if name in ("MIN", "MAX"):
        best = values[0]
        for value in values[1:]:
            order = _compare_order(value, best)
            if name == "MIN" and order < 0:
                best = value
            elif name == "MAX" and order > 0:
                best = value
        return best

    raise QueryError("unknown aggregate: %s" % expr.name)


# ----------------------------------------------------------------------
# Query planning


def _select_items(query: Query, table: Table):
    if query.select_star:
        return [Column(header) for header in table.headers]
    return query.select


def _output_names(query: Query, table: Table, sql: str) -> List[str]:
    names = []
    for item in _select_items(query, table):
        if item.alias is not None:
            names.append(item.alias)
        elif isinstance(item.expr, Column):
            index = _resolve_column(table, item.expr.name)
            names.append(table.headers[index])
        elif item.expr.span is not None:
            start, end = item.expr.span
            names.append(sql[start:end])
        else:
            names.append("")
    return names


def _resolve_order(query: Query, names: Sequence[str]):
    """Return (kind, value) where kind is 'output' (index) or 'expression'."""
    output_positions: Dict[str, int] = {}
    for index, name in enumerate(names):
        output_positions.setdefault(name.casefold(), index)

    resolved = []
    for item in query.order_by:
        expr = item.expr
        if isinstance(expr, Column) and expr.name.casefold() in output_positions:
            resolved.append(("output", output_positions[expr.name.casefold()]))
            continue
        if (
            isinstance(expr, Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            position = expr.value
            if position < 1 or position > len(names):
                raise QueryError("ORDER BY position %d is out of range" % position)
            resolved.append(("output", position - 1))
            continue
        resolved.append(("expression", expr))
    return resolved


def _compare_sort(left, right, descending: bool) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        return 1 if descending else -1
    if right is None:
        return -1 if descending else 1
    order = _compare_order(left, right)
    return -order if descending else order


# ----------------------------------------------------------------------
# Execution


def execute(query: Query, table: Table, sql: str):
    select_items = _select_items(query, table)
    names = _output_names(query, table, sql)
    order = _resolve_order(query, names)

    grouped = bool(query.group_by)
    if not grouped:
        grouped = any(_contains_aggregate(item.expr) for item in select_items)
    if not grouped and query.having is not None:
        grouped = _contains_aggregate(query.having)
    if not grouped:
        grouped = any(_contains_aggregate(item.expr) for item in query.order_by)

    if query.where is not None:
        _validate_expr(query.where, table, in_where=True)
    for group_expr in query.group_by:
        _validate_expr(group_expr, table, in_group_by=True)

    group_signatures = (
        {_expr_signature(expr) for expr in query.group_by} if grouped else None
    )

    for item in select_items:
        _validate_expr(item.expr, table, group_signatures=group_signatures)
    if query.having is not None:
        _validate_expr(query.having, table, group_signatures=group_signatures)
    for kind, value in order:
        if kind == "expression":
            _validate_expr(value, table, group_signatures=group_signatures)

    filtered = []
    for row in table.rows:
        if query.where is None:
            filtered.append(row)
        else:
            context = EvalContext(table, row=row)
            if _eval_expr(query.where, context) is True:
                filtered.append(row)

    contexts: List[EvalContext] = []
    if not grouped:
        contexts = [EvalContext(table, row=row) for row in filtered]
    elif query.group_by:
        groups = {}
        for row in filtered:
            context = EvalContext(table, row=row)
            values = tuple(_eval_expr(expr, context) for expr in query.group_by)
            key = tuple(_group_key(value) for value in values)
            if key not in groups:
                groups[key] = (values, [])
            groups[key][1].append(row)
        for values, rows in groups.values():
            group_values = {
                _expr_signature(expr): value
                for expr, value in zip(query.group_by, values)
            }
            contexts.append(
                EvalContext(
                    table=table,
                    row=None,
                    group=rows,
                    group_values=group_values,
                )
            )
    else:
        contexts = [
            EvalContext(table=table, row=None, group=filtered, group_values={})
        ]

    projected = []
    for context in contexts:
        if query.having is not None:
            if _eval_expr(query.having, context) is not True:
                continue
        values = tuple(_eval_expr(item.expr, context) for item in select_items)
        projected.append((values, context))

    if query.distinct:
        seen = set()
        unique = []
        for values, context in projected:
            key = tuple(_group_key(value) for value in values)
            if key not in seen:
                seen.add(key)
                unique.append((values, context))
        projected = unique

    if order:
        keyed = []
        for values, context in projected:
            keys = []
            for kind, value in order:
                if kind == "output":
                    keys.append(values[value])
                else:
                    keys.append(_eval_expr(value, context))
            keyed.append((keys, values))

        descending = [item.desc for item in query.order_by]

        def compare(left, right):
            for index, (a, b) in enumerate(zip(left[0], right[0])):
                result = _compare_sort(a, b, descending[index])
                if result:
                    return result
            return 0

        keyed.sort(key=cmp_to_key(compare))
        rows = [values for _keys, values in keyed]
    else:
        rows = [values for values, _context in projected]

    if query.offset:
        rows = rows[query.offset:]
    if query.limit is not None:
        rows = rows[: query.limit]

    return names, rows

