                row = []
                for index in range(len(headers)):
                    raw = raw_row[index] if index < len(raw_row) else ""
                    row.append(_convert_field(raw))
                rows.append(row)
    except FileNotFoundError:
        raise QueryError("unknown table: %s" % name) from None
    except OSError as exc:
        raise QueryError(str(exc)) from None
    except (UnicodeError, csv.Error) as exc:
        raise QueryError(str(exc)) from None

    column_map: Dict[str, int] = {}
    for index, header in enumerate(headers):
        column_map.setdefault(header.casefold(), index)
    return Table(headers, rows, column_map)


def _convert_field(text: str):
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        return int(text)

